css:
body { margin: 0; }
.gauge { box-sizing: border-box; height: 100vh; display: grid; justify-items: center; align-content: center; padding: var(--tile-pad, 14px); color: var(--tile-fg); font-family: var(--font-family); }
svg { width: min(150px, 100%); height: auto; display: block; }
path { fill: none; stroke-width: 14; stroke-linecap: round; }
.track { stroke: var(--c-surface-container-low); }
.fill { stroke: var(--c-primary); transition: stroke-dashoffset var(--motion-spatial, 0s); }
.value { margin-top: -34px; font-size: 28px; line-height: 1; font-weight: var(--weight-strong, 600); font-variant-numeric: tabular-nums; }
.unit { font-size: 14px; font-weight: var(--weight-medium, 500); margin-left: 2px; }
.name { margin-top: 6px; font-size: var(--type-body-s-size, 13px); color: var(--tile-state-fg); text-align: center; }
@media (prefers-reduced-motion: reduce) { .fill { transition: none; } }

