function onHomeyReady(Homey) {
  const settings = Homey.getSettings();
  const fill = document.querySelector('.fill');
  const length = fill.getTotalLength ? fill.getTotalLength() : 201;
  fill.style.strokeDasharray = String(length);
  const min = Number(settings.min) || 0;
  const max = Number(settings.max) > min ? Number(settings.max) : min + 100;
  function show() {
    const device = Homey.devices.get(settings.device);
    const cap = device && device.capabilities[settings.capability];
    const value = cap && typeof cap.value === 'number' ? cap.value : null;
    document.querySelector('.number').textContent = value === null ? '–' : value.toLocaleString(Homey.language(), { maximumFractionDigits: 1 });
    document.querySelector('.unit').textContent = cap && cap.units ? cap.units : '';
    document.querySelector('.name').textContent = device ? device.name : Homey.__('choose');
    const share = value === null ? 0 : Math.min(1, Math.max(0, (value - min) / (max - min)));
    fill.style.strokeDashoffset = String(length * (1 - share));
    document.querySelector('.gauge').setAttribute('aria-label', device ? device.name + ', ' + (value === null ? Homey.__('none') : value + (cap.units ? ' ' + cap.units : '')) : Homey.__('choose'));
  }
  Homey.on('device', show);
  show();
  Homey.ready();
}
